import {parsePresentation,shuffle,grade} from './core.mjs';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let bank=read('sot-bank',[]),history=read('sot-history',[]),session=read('sot-session',null),token=null,expires=0,view='library',lastResult=null;
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{message('Không thể lưu trên trình duyệt. Hãy kiểm tra dung lượng lưu trữ.');return false}}
function message(t){$('message').textContent=t;$('message').hidden=!t}
function saveBank(){write('sot-bank',bank);renderLibrary()}
function switchView(v){if(session&&!session.done&&v!=='practice'){message('Bài đang làm vẫn được tính giờ. Quay lại Luyện đề để tiếp tục.')}view=v;for(const x of ['library','practice','history'])$(x).hidden=x!==v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('breadcrumb').textContent={library:'Ngân hàng câu hỏi',practice:'Luyện đề',history:'Lịch sử làm bài'}[v];if(v==='library')renderLibrary();if(v==='practice')renderPractice();if(v==='history')renderHistory()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
function renderLibrary(){$('total').textContent=bank.length;$('ready').textContent=bank.filter(q=>q.verified&&q.answer).length;$('attempts').textContent=history.length;$('source').textContent=read('sot-source','Nhập slide của bạn hoặc trải nghiệm với bộ câu hỏi mẫu.');const term=$('search').value.toLowerCase(),qs=bank.filter(q=>(!$('unverified').checked||!q.verified)&&q.stem.toLowerCase().includes(term));$('questions').innerHTML=qs.length?qs.map(q=>`<article class="card"><div class="question-top"><span>SLIDE ${q.slide} ${q.url?`· <a href="${esc(q.url)}" target="_blank" rel="noopener">Xem nguồn ↗</a>`:''}</span><span class="tag ${q.verified?'ok':''}">${q.verified?'Đã xác nhận':'Cần kiểm tra'}</span></div><div class="question-title">${esc(q.stem)}</div><div class="options">${q.options.map(o=>`<div class="option">${esc(o.id)}. ${esc(o.text)}</div>`).join('')}</div><div class="question-bottom"><label>Đáp án <select data-answer="${q.id}"><option value="">Chưa biết</option>${q.options.map(o=>`<option ${q.answer===o.id?'selected':''}>${o.id}</option>`).join('')}</select></label><button class="secondary" data-verify="${q.id}">${q.verified?'Bỏ xác nhận':'Xác nhận đáp án'}</button><button class="text" data-edit="${q.id}">Sửa</button><button class="text" data-delete="${q.id}">Xóa</button></div></article>`).join(''):'<div class="empty">Chưa có câu hỏi phù hợp.<br>Nhập Google Slides để bắt đầu buổi ôn tập đầu tiên.</div>';}
$('search').oninput=renderLibrary;$('unverified').onchange=renderLibrary;
$('questions').onchange=e=>{const q=bank.find(q=>q.id===e.target.dataset.answer);if(q){q.answer=e.target.value;q.verified=false;saveBank()}};
$('questions').onclick=e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.verify||b.dataset.delete||b.dataset.edit,q=bank.find(q=>q.id===id);if(!q)return;if(b.dataset.verify){if(!q.answer)return message('Chọn đáp án trước khi xác nhận.');q.verified=!q.verified}if(b.dataset.delete){if(!confirm('Xóa câu hỏi này?'))return;bank=bank.filter(x=>x.id!==id)}if(b.dataset.edit){const stem=prompt('Sửa nội dung câu hỏi',q.stem);if(stem===null)return;q.stem=stem.trim()||q.stem;for(const o of q.options){const t=prompt(`Nội dung đáp án ${o.id}`,o.text);if(t!==null)o.text=t.trim()||o.text}q.verified=false}saveBank()};
$('clear').onclick=()=>{if(confirm('Xóa toàn bộ ngân hàng câu hỏi trên trình duyệt này?')){bank=[];saveBank()}};
$('settings').onclick=()=>{$('origin').textContent=location.origin;$('clientId').value=localStorage.getItem('sot-client')||'';$('config').showModal()};
$('saveConfig').onclick=e=>{const id=$('clientId').value.trim();if(!/^[\w.-]+\.apps\.googleusercontent\.com$/.test(id)){e.preventDefault();return message('Client ID cần có đuôi .apps.googleusercontent.com.')}localStorage.setItem('sot-client',id);message('Đã lưu cấu hình. Bấm Kết nối Google để chọn tài khoản có quyền xem slide.')};
$('connect').onclick=()=>{const id=localStorage.getItem('sot-client');if(!id){$('settings').click();return}if(!window.google?.accounts?.oauth2)return message('Google Identity chưa tải được. Kiểm tra mạng rồi thử lại.');google.accounts.oauth2.initTokenClient({client_id:id,scope:'https://www.googleapis.com/auth/presentations.readonly',callback:r=>{if(r.error)return message('Google từ chối kết nối: '+r.error);if(!google.accounts.oauth2.hasGrantedAllScopes(r,'https://www.googleapis.com/auth/presentations.readonly'))return message('Cần cấp quyền đọc Google Slides.');token=r.access_token;expires=Date.now()+r.expires_in*1000;$('connection').textContent='Đã cấp quyền đọc Slides';$('disconnect').hidden=false;message('Đã kết nối. Dán link slide và bấm Nhập câu hỏi.');},error_callback:()=>message('Cửa sổ Google đã đóng hoặc bị chặn. Hãy thử kết nối lại.')}).requestAccessToken({prompt:'select_account'})};
$('disconnect').onclick=()=>{if(token)google.accounts.oauth2.revoke(token,()=>{});token=null;expires=0;$('connection').textContent='Chưa kết nối';$('disconnect').hidden=true;message('Đã ngắt kết nối. Câu hỏi đã nhập vẫn nằm trên trình duyệt này.');};
$('import').onclick=async()=>{let id;try{const u=new URL($('slideLink').value);if(u.hostname!=='docs.google.com')throw Error();id=u.pathname.match(/^\/presentation\/d\/([\w-]+)/)?.[1];if(!id)throw Error()}catch{return message('Dán link Google Slides hợp lệ: https://docs.google.com/presentation/d/…')}if(!token||Date.now()>=expires)return message('Hãy kết nối Google trước. Nếu phiên hết hạn, bấm Kết nối Google để cấp lại quyền.');$('import').disabled=true;message('Đang đọc slide và ghi chú…');try{const r=await fetch(`https://slides.googleapis.com/v1/presentations/${id}`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok){if(r.status===401){token=null;throw Error('Phiên Google đã hết hạn. Hãy kết nối lại.')}if(r.status===403||r.status===404)throw Error('Không đọc được tài liệu. Kiểm tra đúng Gmail, quyền xem và Google Slides API đã được bật.');throw Error('Google trả lỗi '+r.status)}const p=await r.json(),parsed=parsePresentation(p);if(!parsed.questions.length)throw Error(`Chưa nhận diện được câu trắc nghiệm. Đã kiểm tra ${p.slides?.length||0} slide. Cần câu hỏi dạng chữ với các lựa chọn A. B. C. D. trên từng dòng.`);if(bank.length&&!confirm('Thay ngân hàng hiện tại bằng câu hỏi của slide này?')){message('Đã giữ ngân hàng hiện tại.');return}bank=parsed.questions;write('sot-source',p.title);saveBank();message(`Đã nhập ${bank.length} câu; bỏ qua ${parsed.skipped.length} slide không nhận diện được câu trắc nghiệm${parsed.skipped.length?' (slide '+parsed.skipped.join(', ')+')':''}. Kiểm tra nội dung và xác nhận đáp án trước khi luyện.`)}catch(e){message(e.message)}finally{$('import').disabled=false}};
$('demo').onclick=()=>{if(bank.length&&!confirm('Thay ngân hàng hiện tại bằng bộ mẫu?'))return;bank=[{stem:'What is an index?',options:[{id:'A',text:'A database structure that speeds up data retrieval.'},{id:'B',text:'The same as an alias.'},{id:'C',text:'A special way to join two or more tables.'},{id:'D',text:'A database row attribute.'}],answer:'A'},{stem:'Which SQL clause filters groups after aggregation?',options:[{id:'A',text:'WHERE'},{id:'B',text:'HAVING'},{id:'C',text:'ORDER BY'},{id:'D',text:'SELECT'}],answer:'B'},{stem:'Which constraint uniquely identifies each row in a table?',options:[{id:'A',text:'FOREIGN KEY'},{id:'B',text:'DEFAULT'},{id:'C',text:'PRIMARY KEY'},{id:'D',text:'CHECK'}],answer:'C'}].map((q,i)=>({...q,id:crypto.randomUUID(),verified:true,slide:i+1}));write('sot-source','Bộ câu hỏi mẫu · Database fundamentals');saveBank();message('Đây là 3 câu mẫu để thử luồng luyện đề, chưa phải dữ liệu slide của bạn.')};
function renderPractice(){if(session&&!session.done)return renderQuiz();if(lastResult)return renderResult(lastResult);const n=bank.filter(q=>q.verified&&q.answer).length;$('practice').innerHTML=`<div class="card"><div class="eyebrow">BUỔI LUYỆN CỦA BẠN</div><h2 style="margin-top:16px">Một đề mới, một bước tiến</h2><p>Có ${n} câu đã xác nhận. Câu hỏi được chọn ngẫu nhiên từ ngân hàng.</p><label>Số câu<input id="count" type="number" min="1" max="${n}" value="${Math.min(n,20)||1}"></label><br><label>Thời gian (phút)<input id="minutes" type="number" min="1" max="180" value="20"></label><div class="row"><label><input type="checkbox" id="mix" checked> Đảo thứ tự đáp án</label></div><button id="start" ${!n?'disabled':''}>Bắt đầu luyện đề →</button></div>`;$('start').onclick=()=>{const count=Number($('count').value),mins=Number($('minutes').value);if(!Number.isInteger(count)||count<1||count>n||!Number.isInteger(mins)||mins<1||mins>180)return message('Số câu hoặc thời gian không hợp lệ.');const mix=$('mix').checked;session={questions:shuffle(bank.filter(q=>q.verified&&q.answer)).slice(0,count).map(q=>({...q,options:mix?shuffle(q.options):q.options})),answers:{},flags:[],started:Date.now(),deadline:Date.now()+mins*60000,done:false};write('sot-session',session);message('');renderQuiz()}}
function renderQuiz(){$('practice').innerHTML=`<div class="quiz-head"><div><h2>Đề luyện tập</h2><span id="progress"></span></div><div class="timer" id="timer"></div><button id="submit">Nộp bài</button></div>${session.questions.map((q,i)=>`<article class="card"><div class="question-top"><span>CÂU ${i+1} / ${session.questions.length}</span><label><input type="checkbox" data-flag="${q.id}" ${session.flags.includes(q.id)?'checked':''}> Xem lại</label></div><div class="question-title">${esc(q.stem)}</div><div class="options">${q.options.map((o,j)=>`<button class="option ${session.answers[q.id]===o.id?'selected':''}" data-q="${q.id}" data-o="${o.id}">${String.fromCharCode(65+j)}. ${esc(o.text)}</button>`).join('')}</div></article>`).join('')}`;$('submit').onclick=()=>{if(confirm(`Nộp bài? Đã trả lời ${Object.keys(session.answers).length}/${session.questions.length} câu.`))finish()};updateTimer()}
$('practice').onclick=e=>{const b=e.target.closest('[data-q]');if(!b||!session||session.done)return;if(Date.now()>=session.deadline)return finish();session.answers[b.dataset.q]=b.dataset.o;write('sot-session',session);b.parentNode.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));updateTimer()};
$('practice').onchange=e=>{const id=e.target.dataset.flag;if(!id||!session||session.done)return;session.flags=e.target.checked?[...new Set([...session.flags,id])]:session.flags.filter(x=>x!==id);write('sot-session',session)};
function updateTimer(){if(!session||session.done)return;const left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));if($('timer'))$('timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if($('progress'))$('progress').textContent=`${Object.keys(session.answers).length}/${session.questions.length} câu đã trả lời`;if(!left)finish()}
function finish(){if(!session||session.done)return;session.done=true;const result={...session,id:crypto.randomUUID(),finished:Date.now(),correct:grade(session.questions,session.answers)};history.unshift(result);history=history.slice(0,50);write('sot-history',history);write('sot-session',null);session=null;lastResult=result;switchView('practice');message('Đã nộp bài và lưu kết quả trên trình duyệt này.')}
function renderResult(r){$('practice').innerHTML=`<div class="card"><div class="eyebrow">ĐÃ HOÀN THÀNH</div><div class="score">${(r.correct/r.questions.length*10).toFixed(1)}<small> / 10</small></div><h2>Đúng ${r.correct} / ${r.questions.length} câu</h2><p>Thời gian: ${Math.ceil((Math.min(r.finished,r.deadline)-r.started)/60000)} phút · Chưa trả lời: ${r.questions.filter(q=>!r.answers[q.id]).length} câu</p><div class="row"><button id="again">Tạo đề mới</button><button id="retry" class="secondary">Luyện lại câu sai</button></div></div>${r.questions.map((q,i)=>`<div class="card"><div class="question-top">CÂU ${i+1} · ${r.answers[q.id]===q.answer?'Đúng':r.answers[q.id]?'Sai':'Chưa trả lời'}</div><div class="question-title">${esc(q.stem)}</div><div class="options">${q.options.map(o=>`<div class="option ${o.id===q.answer?'correct':o.id===r.answers[q.id]?'wrong':''}">${esc(o.text)} ${o.id===q.answer?'✓':''} ${o.id===r.answers[q.id]?'← Bạn chọn':''}</div>`).join('')}</div></div>`).join('')}`;$('again').onclick=()=>{lastResult=null;renderPractice()};$('retry').onclick=()=>{const qs=r.questions.filter(q=>r.answers[q.id]!==q.answer);if(!qs.length)return message('Bạn đã trả lời đúng toàn bộ câu hỏi.');session={questions:shuffle(qs),answers:{},flags:[],started:Date.now(),deadline:Date.now()+Math.max(5,qs.length)*60000,done:false};write('sot-session',session);renderQuiz()}}
function renderHistory(){$('history').innerHTML='<h2 style="margin-top:25px">Những lần bạn tiến bộ</h2>'+ (history.length?history.map(r=>`<div class="card"><div class="question-top">${new Date(r.finished).toLocaleString('vi-VN')}</div><h2>${(r.correct/r.questions.length*10).toFixed(1)} / 10 điểm</h2><p>Đúng ${r.correct}/${r.questions.length} câu</p><button class="secondary" data-result="${r.id}">Xem bài làm →</button></div>`).join(''):'<div class="empty">Chưa có bài đã nộp. Bắt đầu một đề luyện tập nhé.</div>')}
$('history').onclick=e=>{const id=e.target.closest('[data-result]')?.dataset.result;if(!id)return;if(session&&!session.done)return message('Hãy hoàn thành bài đang làm trước khi xem lại kết quả.');lastResult=history.find(r=>r.id===id);switchView('practice')};
setInterval(updateTimer,1000);document.addEventListener('visibilitychange',updateTimer);renderLibrary();if(session&&!session.done)switchView('practice');
